WITH with_latest AS (SELECT s.*, x.shipping_fee FROM stores s LEFT JOIN LATERAL (SELECT c.shipping_fee FROM orders c WHERE c.store_id = s.id AND c.order_date <= s.opened_date ORDER BY c.order_date DESC, c.id DESC LIMIT 1) x ON TRUE) SELECT id, city, opened_date, sqft, shipping_fee, CASE WHEN city RLIKE '^(New York|Tokyo)$' THEN 'OTHER_ZONE' WHEN city RLIKE '^(Bangkok|Chiang Mai)$' THEN 'GROUP_B' ELSE 'EXTENDED' END AS city_zone FROM with_latest
